enum class ScanAction { Open, RequestPermission }

fun scanAction(hasPermission: () -> Boolean): ScanAction =
    if (hasPermission()) ScanAction.Open else ScanAction.RequestPermission

/** Opens the camera to scan a coupon code at checkout. */
object CouponScanner {
    fun hasCameraAccess(context: Context): Boolean =
        ContextCompat.checkSelfPermission(context, Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED

    @SuppressLint("MissingPermission")
    fun open(context: Context, onResult: (String) -> Unit) {
        val cameras = context.getSystemService(CameraManager::class.java)
        val cameraId = cameras.cameraIdList.firstOrNull() ?: return onResult("No camera on this device")
        try {
            cameras.openCamera(cameraId, object : CameraDevice.StateCallback() {
                override fun onOpened(camera: CameraDevice) {
                    camera.close()
                    onResult("Scanner ready: point the camera at your coupon")
                }

                override fun onDisconnected(camera: CameraDevice) = camera.close()

                override fun onError(camera: CameraDevice, error: Int) {
                    camera.close()
                    onResult("Camera error $error")
                }
            }, Handler(Looper.getMainLooper()))
        } catch (e: SecurityException) {
            onResult("Camera permission is needed to scan coupons")
        }
    }
}

when (scanAction { CouponScanner.hasCameraAccess(context) }) {
    ScanAction.Open -> CouponScanner.open(context) { status = it }
    ScanAction.RequestPermission -> askCamera.launch(Manifest.permission.CAMERA)
}

